import { chromium } from '@playwright/test';

const SHOT_DIR = '/tmp/web_qa_shots';
import { mkdirSync } from 'fs';
mkdirSync(SHOT_DIR, { recursive: true });

async function run() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 390, height: 844 }, // iPhone 14 dimensions
    userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1',
    deviceScaleFactor: 3,
    isMobile: true,
    hasTouch: true,
  });
  const page = await context.newPage();

  // ============================================================
  // TEST 1: chat.ivxholding.com — Expo web app (owner chat)
  // ============================================================
  console.log('\n=== TEST 1: chat.ivxholding.com (Expo web app) ===');
  let chatResult = { loaded: false, title: '', hasChat: false, hasFlatList: false, error: null };
  try {
    const response = await page.goto('https://chat.ivxholding.com', { waitUntil: 'networkidle', timeout: 30000 });
    console.log('HTTP status:', response?.status());
    chatResult.loaded = response?.status() === 200;
    await page.waitForTimeout(3000); // let JS hydrate

    const title = await page.title();
    console.log('Title:', title);
    chatResult.title = title;

    // Screenshot the initial load
    await page.screenshot({ path: `${SHOT_DIR}/01_chat_initial.png`, fullPage: false });
    console.log('Screenshot: 01_chat_initial.png');

    // Check what's on the page
    const bodyText = await page.textContent('body');
    console.log('Body text (first 300 chars):', bodyText?.substring(0, 300));

    // Check for Expo root content
    const rootHTML = await page.evaluate(() => {
      const root = document.getElementById('root');
      return root ? root.innerHTML.substring(0, 500) : 'NO ROOT';
    });
    console.log('Root content (first 500 chars):', rootHTML?.substring(0, 500));

    // Check if there are any chat-related elements
    const chatElements = await page.evaluate(() => {
      const all = document.querySelectorAll('*');
      const classes = new Set();
      all.forEach(el => {
        if (el.className && typeof el.className === 'string') {
          el.className.split(' ').forEach(c => {
            if (c.includes('chat') || c.includes('message') || c.includes('flat') || c.includes('scroll') || c.includes('bubble') || c.includes('list')) {
              classes.add(c);
            }
          });
        }
      });
      return Array.from(classes);
    });
    console.log('Chat-related CSS classes:', JSON.stringify(chatElements));
    chatResult.hasChat = chatElements.length > 0;

    // Check for FlatList (react-native-web renders as div with specific structure)
    const flatListCheck = await page.evaluate(() => {
      const scrollViews = document.querySelectorAll('[class*="scroll"], [class*="flat"]');
      return {
        scrollCount: scrollViews.length,
        hasInverted: Array.from(scrollViews).some(el => {
          const style = window.getComputedStyle(el);
          return style.flexDirection === 'column-reverse';
        })
      };
    });
    console.log('Scroll/FlatList check:', JSON.stringify(flatListCheck));
    chatResult.hasFlatList = flatListCheck.hasInverted;

    // Check for RSC error or hydration error
    const errors = await page.evaluate(() => {
      return (window.__expo_errors || []).map(e => String(e).substring(0, 200));
    });
    if (errors.length > 0) console.log('Expo errors:', errors);

    // Check console errors
    const consoleErrors = [];
    page.on('console', msg => {
      if (msg.type() === 'error') consoleErrors.push(msg.text().substring(0, 200));
    });

    // Look for login/auth redirect
    const currentURL = page.url();
    console.log('Current URL after load:', currentURL);

    // Check for any visible text about login or auth
    const loginCheck = await page.evaluate(() => {
      const text = document.body?.innerText || '';
      return {
        hasLogin: /log ?in|sign ?in|auth/i.test(text),
        hasChat: /chat|message|send/i.test(text),
        hasIVX: /ivx/i.test(text),
      };
    });
    console.log('Content check:', JSON.stringify(loginCheck));

  } catch (err) {
    chatResult.error = err.message;
    console.log('ERROR:', err.message);
    await page.screenshot({ path: `${SHOT_DIR}/01_chat_error.png` }).catch(() => {});
  }

  // ============================================================
  // TEST 2: ivxholding.com — Landing page with support chat widget
  // ============================================================
  console.log('\n=== TEST 2: ivxholding.com (landing + support chat widget) ===');
  let landingResult = { loaded: false, hasChatWidget: false, chatResponds: false, error: null };
  try {
    const page2 = await context.newPage();
    const response = await page2.goto('https://ivxholding.com', { waitUntil: 'domcontentloaded', timeout: 30000 });
    console.log('HTTP status:', response?.status());
    landingResult.loaded = response?.status() === 200;
    await page2.waitForTimeout(2000);
    await page2.screenshot({ path: `${SHOT_DIR}/02_landing_initial.png`, fullPage: false });
    console.log('Screenshot: 02_landing_initial.png');

    // Scroll to the investor-chat section
    const chatSection = await page2.$('#investor-chat');
    if (chatSection) {
      console.log('Found #investor-chat section');
      await chatSection.scrollIntoViewIfNeeded();
      await page2.waitForTimeout(1000);
      await page2.screenshot({ path: `${SHOT_DIR}/03_landing_chat_section.png`, fullPage: false });
      console.log('Screenshot: 03_landing_chat_section.png');
      landingResult.hasChatWidget = true;

      // Check for the support chat widget
      const chatWidget = await page2.$('.landing-chat-widget, .support-chat, [class*="chat-input"], [class*="chat-message"], #chat-input, .chat-bubble');
      if (chatWidget) {
        console.log('Found chat widget element');
        // Try to type a message
        const input = await page2.$('input[type="text"], textarea, [contenteditable]');
        if (input) {
          console.log('Found input field, typing test message...');
          await input.fill('Hello, this is a QA test message');
          await page2.waitForTimeout(500);
          await page2.screenshot({ path: `${SHOT_DIR}/04_chat_typed.png`, fullPage: false });

          // Try to send
          const sendBtn = await page2.$('button[class*="send"], button[class*="chat"], [class*="send-button"]');
          if (sendBtn) {
            console.log('Found send button, clicking...');
            await sendBtn.click();
            await page2.waitForTimeout(3000);
            await page2.screenshot({ path: `${SHOT_DIR}/05_chat_response.png`, fullPage: false });
            console.log('Screenshot: 05_chat_response.png');
            landingResult.chatResponds = true;
          } else {
            console.log('No send button found');
            // Try Enter key
            await input.press('Enter');
            await page2.waitForTimeout(3000);
            await page2.screenshot({ path: `${SHOT_DIR}/05_chat_response.png`, fullPage: false });
          }
        } else {
          console.log('No input field found in chat section');
        }
      } else {
        console.log('No chat widget element found (checking for any chat UI)...');
        // Check what's actually in the investor-chat section
        const sectionHTML = await page2.evaluate(() => {
          const section = document.getElementById('investor-chat');
          return section ? section.innerHTML.substring(0, 800) : 'NOT FOUND';
        });
        console.log('Section HTML (first 800 chars):', sectionHTML);
      }
    } else {
      console.log('No #investor-chat section found');
    }

    // Check for any chat-related JavaScript loaded
    const chatScripts = await page2.evaluate(() => {
      const scripts = Array.from(document.querySelectorAll('script[src]'));
      return scripts.map(s => s.src).filter(src => src.includes('chat'));
    });
    console.log('Chat scripts loaded:', JSON.stringify(chatScripts));

    // Check the landing-support-chat.js is loaded
    const supportChatLoaded = await page2.evaluate(() => {
      return typeof window.openSupportChat !== 'undefined' || typeof window.landingChat !== 'undefined' || !!document.querySelector('.landing-chat-widget');
    });
    console.log('Support chat JS loaded:', supportChatLoaded);

  } catch (err) {
    landingResult.error = err.message;
    console.log('ERROR:', err.message);
  }

  // ============================================================
  // TEST 3: Check the inverted FlatList CSS on web
  // ============================================================
  console.log('\n=== TEST 3: Inverted FlatList CSS verification ===');
  let invertedResult = { found: false, direction: '', error: null };
  try {
    const page3 = await context.newPage();
    await page3.goto('https://chat.ivxholding.com', { waitUntil: 'networkidle', timeout: 30000 });
    await page3.waitForTimeout(3000);

    // In react-native-web, FlatList with inverted={true} applies
    // flexDirection: column-reverse to the scroll container
    const invertedCheck = await page3.evaluate(() => {
      const allEls = document.querySelectorAll('*');
      const results = [];
      allEls.forEach(el => {
        const style = window.getComputedStyle(el);
        if (style.flexDirection === 'column-reverse') {
          results.push({
            tag: el.tagName,
            class: el.className?.substring(0, 80),
            flexDirection: style.flexDirection,
            overflow: style.overflowY,
            height: style.height,
          });
        }
      });
      return results.slice(0, 5);
    });
    console.log('Elements with flexDirection: column-reverse:', JSON.stringify(invertedCheck, null, 2));
    invertedResult.found = invertedCheck.length > 0;
    invertedResult.direction = invertedCheck.length > 0 ? 'column-reverse' : 'not found';

  } catch (err) {
    invertedResult.error = err.message;
    console.log('ERROR:', err.message);
  }

  // ============================================================
  // SUMMARY
  // ============================================================
  console.log('\n=== WEB QA SUMMARY ===');
  console.log(JSON.stringify({
    chatApp: chatResult,
    landing: landingResult,
    invertedFlatList: invertedResult,
  }, null, 2));

  await browser.close();
}

run().catch(err => { console.error('FATAL:', err); process.exit(1); });
