        return Array.from(document.querySelectorAll('button, [role="button"]')).map(b => ({
          text: b.textContent?.trim().substring(0, 50),
          class: b.className?.substring(0, 60),
        }));
      });
      console.log('Buttons:', JSON.stringify(buttons.slice(0, 10), null, 2));
    }

