      try {
        // Try to find the supabase client on the global scope or module
        // In Expo web, it might be accessible via the module registry
        const supabaseUrl = 'https://kvclcdjmjghndxsngfzb.supabase.co';
        const anonKey = document.querySelector('meta[name="supabase-anon-key"]')?.getAttribute('content');

        // Try to call Supabase auth REST API directly
        const response = await fetch(`${supabaseUrl}/auth/v1/token?grant_type=password`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'apikey': anonKey || '',
          },
          body: JSON.stringify({
            email: 'iperez4242@gmail.com',
            password: 'ivx_emergency_recovery',
          }),
        });
        const data = await response.json();
        return { status: response.status, hasToken: !!data.access_token, error: data.error || data.msg };
      } catch (e) {
        return { error: e.message };
      }
    });
    console.log('Direct auth result:', JSON.stringify(authResult));
  }

  // ============================================================
