import { chromium } from '@playwright/test';
import { mkdirSync, readFileSync } from 'fs';

const SHOT_DIR = '/tmp/web_qa_shots';
mkdirSync(SHOT_DIR, { recursive: true });

const sessionData = JSON.parse(readFileSync('/tmp/supabase_session.json', 'utf-8'));
const STORAGE_KEY = sessionData.key;
const SESSION_VALUE = sessionData.value;

async function run() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 390, height: 844 },
    userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1',
    deviceScaleFactor: 3,
    isMobile: true,
    hasTouch: true,
  });

  // Inject localStorage BEFORE any JS runs
  await context.addInitScript((payload) => {
    try {
      localStorage.setItem(payload.key, payload.value);
      localStorage.setItem('ipx_user_id', '9b280e15-f9fd-459f-bf2d-530b1ed84cb1');
      localStorage.setItem('ipx_user_role', 'owner');
    } catch (e) {}
  }, { key: STORAGE_KEY, value: SESSION_VALUE });

  const page = await context.newPage();

  // Intercept ALL fetch/XHR requests to api.ivxholding.com
  // If backend is hibernating (503), return mock success responses
  // This lets the Supabase session work without the backend
  await page.route('**/api.ivxholding.com/**', async (route) => {
    const url = route.request().url();
    const method = route.request().method();

    // Try the real request first
    try {
      const response = await route.fetch({ timeout: 8000 });
      const status = response.status();

      if (status === 503 || status === 0) {
        // Backend hibernating — return mock response
        if (url.includes('owner-bootstrap')) {
          return route.fulfill({
            status: 200,
            contentType: 'application/json',
            body: JSON.stringify({
              ok: true,
              ownerVerified: true,
              accountType: 'owner',
              role: 'owner',
              kycStatus: 'approved',
            }),
          });
        }
        if (url.includes('owner-registration/status')) {
          return route.fulfill({
            status: 200,
            contentType: 'application/json',
            body: JSON.stringify({ ok: true, routeRegistered: true }),
          });
        }
        // Generic mock for other API calls
        return route.fulfill({
          status: 200,
          contentType: 'application/json',
          body: JSON.stringify({ ok: true }),
        });
      }

      // Real response was OK — pass through
      return route.fulfill({
        status: response.status(),
        headers: response.headers(),
        body: await response.body(),
      });
    } catch (err) {
      // Request failed entirely — mock it
      if (url.includes('owner-bootstrap')) {
        return route.fulfill({
          status: 200,
          contentType: 'application/json',
          body: JSON.stringify({
            ok: true,
            ownerVerified: true,
            accountType: 'owner',
            role: 'owner',
            kycStatus: 'approved',
          }),
        });
      }
      return route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ ok: true }),
      });
    }
  });

  // Also intercept Supabase auth calls to ensure session is accepted
  await page.route('**/kvclcdjmjghndxsngfzb.supabase.co/auth/v1/**', async (route) => {
    // Let Supabase auth requests pass through (hosted Supabase is always up)
    return route.continue();
  });

  const consoleErrors = [];
  const consoleLogs = [];
  page.on('console', msg => {
    const text = msg.text().substring(0, 300);
    if (msg.type() === 'error') consoleErrors.push(text);
    if (msg.type() === 'log') consoleLogs.push(text);
  });
  page.on('pageerror', err => {
    consoleErrors.push('PAGE_ERROR: ' + err.message.substring(0, 300));
  });

  // ============================================================
  // STEP 1: Load with session + API mocking
  // ============================================================
  console.log('\n=== STEP 1: Load with session + API mocking ===');
  const resp = await page.goto('https://chat.ivxholding.com', { waitUntil: 'networkidle', timeout: 45000 });
  console.log('HTTP status:', resp?.status());
  console.log('URL after load:', page.url());
  await page.waitForTimeout(6000); // Let auth context fully initialize
  console.log('URL after 6s wait:', page.url());
  await page.screenshot({ path: `${SHOT_DIR}/30_mocked_load.png` });

  const isLogin = page.url().includes('/login');
  console.log('On login page?', isLogin);

  // ============================================================
  // STEP 2: If still on login, check why
  // ============================================================
  if (isLogin) {
    console.log('\n=== STEP 2: Still on login — check auth state ===');

    // Check what localStorage looks like now
    const storageState = await page.evaluate(() => {
      const keys = Object.keys(localStorage);
      const sbKey = keys.find(k => k.startsWith('sb-') && k.includes('auth-token'));
      return {
        totalKeys: keys.length,
        sbKey: sbKey,
        sbValue: sbKey ? localStorage.getItem(sbKey)?.substring(0, 100) : null,
        userId: localStorage.getItem('ipx_user_id'),
        userRole: localStorage.getItem('ipx_user_role'),
      };
    });
    console.log('Storage state:', JSON.stringify(storageState, null, 2));

    // Check console logs for auth-related messages
    const authLogs = consoleLogs.filter(l =>
      l.includes('auth') || l.includes('Auth') || l.includes('session') || l.includes('Session') || l.includes('login') || l.includes('redirect')
    );
    console.log('Auth-related logs:', authLogs.slice(0, 10));
    console.log('Console errors:', consoleErrors.slice(0, 10));

    // Try navigating directly to chat
    console.log('\n=== STEP 2b: Navigate to /ivx/chat directly ===');
    await page.goto('https://chat.ivxholding.com/ivx/chat', { waitUntil: 'networkidle', timeout: 30000 });
    await page.waitForTimeout(5000);
    console.log('URL:', page.url());
    await page.screenshot({ path: `${SHOT_DIR}/31_ivx_chat_direct.png` });

    const bodyText = await page.textContent('body');
    console.log('Body text (first 300):', bodyText?.substring(0, 300));
  }

  // ============================================================
  // STEP 3: Check for inverted FlatList and chat elements
  // ============================================================
  console.log('\n=== STEP 3: DOM analysis ===');
  const domCheck = await page.evaluate(() => {
    const allEls = document.querySelectorAll('*');
    const columnReverseEls = [];
    const scrollEls = [];
    const chatEls = [];

    allEls.forEach(el => {
      const style = window.getComputedStyle(el);
      const cls = (el.className || '').toString();

      if (style.flexDirection === 'column-reverse') {
        columnReverseEls.push({
          tag: el.tagName,
          class: cls.substring(0, 80),
          childCount: el.children.length,
          scrollHeight: el.scrollHeight,
          clientHeight: el.clientHeight,
        });
      }

      if (style.overflowY === 'auto' || style.overflowY === 'scroll') {
        scrollEls.push({
          tag: el.tagName,
          class: cls.substring(0, 80),
          flexDirection: style.flexDirection,
          childCount: el.children.length,
          scrollHeight: el.scrollHeight,
          clientHeight: el.clientHeight,
        });
      }

      if (cls.includes('chat') || cls.includes('message') || cls.includes('bubble') || cls.includes('msg')) {
        chatEls.push({
          tag: el.tagName,
          class: cls.substring(0, 80),
          text: (el.textContent || '').substring(0, 100),
        });
      }
    });

    return {
      columnReverse: columnReverseEls.slice(0, 5),
      scroll: scrollEls.slice(0, 5),
      chat: chatEls.slice(0, 10),
      totalEls: allEls.length,
    };
  });
  console.log('DOM check:', JSON.stringify(domCheck, null, 2));

  // ============================================================
  // STEP 4: Final screenshots
  // ============================================================
  await page.screenshot({ path: `${SHOT_DIR}/32_final.png`, fullPage: true });
  console.log('Final screenshot saved');

  // ============================================================
  // SUMMARY
  // ============================================================
  console.log('\n=== FINAL WEB QA SUMMARY ===');
  console.log(JSON.stringify({
    finalURL: page.url(),
    onLogin: page.url().includes('/login'),
    pastLogin: !page.url().includes('/login'),
    hasInvertedFlatList: domCheck.columnReverse.length > 0,
    hasChatElements: domCheck.chat.length > 0,
    totalConsoleErrors: consoleErrors.length,
  }, null, 2));

  await browser.close();
}

run().catch(err => { console.error('FATAL:', err); process.exit(1); });
